```java
import javafx.scene.layout.Background;
import javafx.scene.layout.BackgroundFill;
import javafx.scene.paint.Color;

// Variante 1: Background-Objekt (null, null = keine abgerundeten Ecken, kein Einzug)
outputField.setBackground(new Background(
        new BackgroundFill(Color.LIGHTGREEN, null, null)));
// Variante 2: CSS
outputField.setStyle("-fx-background-color: lightgreen;");

// Hintergrund aller GUI-Elemente
vContainer.setBackground(new Background(
        new BackgroundFill(Color.LIGHTYELLOW, null, null)));
pressButton.setBackground(new Background(
        new BackgroundFill(Color.LIGHTBLUE, null, null)));
// bzw. per CSS
