```java
import javafx.application.Application;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;

public class Main extends Application {

    // Zustand als Attribut (nicht als lokale Variable in start()!)
    private boolean eingeschaltet = false;

    @Override
    public void start(Stage primaryStage) throws Exception {
        primaryStage.setTitle("Button Press");

        Button pressButton = new Button("Drück mich!");
        Label outputField = new Label("Der Knopf wurde noch nicht gedrückt!");
        outputField.setStyle("-fx-text-fill: blue;");

        pressButton.setOnAction(event -> {
            eingeschaltet = !eingeschaltet;          // Zustand umschalten
            if (eingeschaltet) {
                outputField.setText("eingeschaltet");
                outputField.setStyle("-fx-font-weight: bold;" +
                                     "-fx-font-size: 16;" +
                                     "-fx-text-fill: rgb(180,20,20);");
            } else {
                outputField.setText("ausgeschaltet");
                outputField.setStyle("-fx-text-fill: limegreen;");
            }
        });

        VBox vContainer = new VBox();
        vContainer.getChildren().addAll(pressButton, outputField);
        vContainer.setAlignment(Pos.CENTER);
        vContainer.setSpacing(10);

        Scene scene = new Scene(vContainer, 270, 100);
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}
```

- Der Starttext wird im Konstruktor des Labels gesetzt; der erste Klick schaltet `false → true` und zeigt „eingeschaltet“.
- Jeder Zustand setzt seinen **vollständigen** Style-String; weil `setStyle` den alten String ersetzt, verschwinden „fett“ und „16“ beim Wechsel zu „ausgeschaltet“ automatisch.

**Alternative im Stil der Vorlesung** (eigene Controller-Klasse als Beobachter):
```java
import javafx.event.ActionEvent;
import javafx.event.EventHandler;
import javafx.scene.control.Label;

public class Controller implements EventHandler<ActionEvent> {
    private Label outputField;
    private boolean eingeschaltet = false;

    public Controller(Label outputField) {
        this.outputField = outputField;
    }

    @Override
    public void handle(ActionEvent event) {
        eingeschaltet = !eingeschaltet;
        if (eingeschaltet) {
            outputField.setText("eingeschaltet");
        } else {
            outputField.setText("ausgeschaltet");
        }
    }
}
// in start(): pressButton.setOnAction(new Controller(outputField));
```

