```java
import javafx.application.Application;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;

public class CounterApp extends Application {

    private int counter = 0;

    @Override
    public void start(Stage primaryStage) {
        Label outputField = new Label("Der Knopf wurde noch nicht gedrückt!");
        Button pressButton = new Button("Drück mich!");
        Button resetButton = new Button("Zurücksetzen");

        pressButton.setOnAction(event -> {
            counter++;
            outputField.setText("Der Knopf wurde " + counter + "-mal gedrückt!");
        });

        resetButton.setOnAction(event -> {
            counter = 0;
            outputField.setText("Der Knopf wurde noch nicht gedrückt!");
        });

        VBox vContainer = new VBox();
        vContainer.getChildren().addAll(pressButton, resetButton, outputField);
        vContainer.setAlignment(Pos.CENTER);
        vContainer.setSpacing(10);

        Scene scene = new Scene(vContainer, 300, 150);
        primaryStage.setTitle("Zähler");
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}
```

- Der Zähler muss ein **Attribut** sein, weil er in den Lambdas verändert wird.
- Jeder Button bekommt seinen eigenen Handler über `setOnAction`.

*(Musterlösung selbst erstellt)*

```java
import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.TextField;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;

public class Main extends Application {
    @Override
    public void start(Stage primaryStage) throws Exception {
        TextField textInputField = new TextField("<Enter your name>"); // NEU
        Button button = new Button("Show welcome message");
        Label textOutputLabel = new Label("Welcome!");

        VBox vBox = new VBox();
        vBox.getChildren().add(textInputField);   // ganz oben
        vBox.getChildren().add(button);
        vBox.getChildren().add(textOutputLabel);

        Scene scene = new Scene(vBox, 250, 120);
        primaryStage.setTitle("Welcome");
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}
```

**Geeignete Stelle:** In der vertikalen Box werden die Kinder in der Reihenfolge der `add`-Aufrufe von oben nach unten angeordnet. Damit das Textfeld wie in der Abbildung oben steht, muss es **vor** dem Button hinzugefügt werden (alternativ `vBox.getChildren().add(0, textInputField)` in ein bestehendes Projekt).

Hinweis: Das Konstruktor-Argument von `TextField(String)` ist der **Anfangstext** – er muss vor der Eingabe gelöscht werden. Ein grauer Hinweistext, der beim Tippen verschwindet, entsteht mit `textInputField.setPromptText("<Enter your name>")`.

*(Musterlösung selbst erstellt)*

**Variante 1 – Lambda-Ausdruck** (kurz, in `start()` nach dem Erzeugen der Controls):

```java
button.setOnAction(event -> {
    textOutputLabel.setText("Welcome "
            + textInputField.getText() + "!");
});
```

**Variante 2 – anonyme innere Klasse** (wie in der Vorlesung):

```java
button.setOnAction(new EventHandler<ActionEvent>() {
    @Override
    public void handle(ActionEvent event) {
        textOutputLabel.setText("Welcome "
                + textInputField.getText() + "!");
    }
});
```

Benötigte Imports für Variante 2: `javafx.event.ActionEvent`, `javafx.event.EventHandler`.

Ablauf (Beobachter-Muster): Der Handler wird mit `setOnAction` beim Button angemeldet; beim Klick ruft der Button `handle()` auf. Dort wird der aktuelle Text des Textfelds gelesen und in das Label geschrieben. Eingabe „Java Expert“ → Label „Welcome Java Expert!“.

*(Musterlösung selbst erstellt)*

```java
VBox vBox = new VBox();
vBox.getChildren().addAll(textInputField, button, textOutputLabel);

vBox.setPadding(new Insets(10, 10, 10, 10)); // Rand: oben, rechts, unten, links
vBox.setSpacing(10);                          // Abstand zwischen den Elementen
vBox.setAlignment(Pos.CENTER);                // Elemente zentrieren

button.setOnAction(event -> {
    textOutputLabel.setText("Welcome " + textInputField.getText() + "!");
    // optional wie im dritten Screenshot:
    vBox.setStyle("-fx-background-color: lightgreen;");
    textOutputLabel.setStyle("-fx-font-weight: bold;"
            + "-fx-text-fill: rgb(180,20,20);");
});
```

Imports: `javafx.geometry.Insets`, `javafx.geometry.Pos`.

- `setPadding` erzeugt einen inneren Rand zwischen Box-Rand und Inhalt.
- `setSpacing` legt den Abstand **zwischen** den Kindern fest.
- `setAlignment(Pos.CENTER)` zentriert die Kinder; das `TextField` wird von der VBox auf die volle Breite gezogen, Button und Label behalten ihre bevorzugte Breite und stehen deshalb mittig.
- Mehrere `setStyle`-Aufrufe auf dasselbe Element überschreiben sich – daher alle CSS-Angaben in einem String verknüpfen (Praktikum 1).

