public class ButtonImageController {

    @FXML
    private VBox buttonBox;      // linke Seite: Schaltflächen
    @FXML
    private FlowPane flowPane;   // rechte Seite: Zusammenstellung

    // imagePath, outputImageWidth, outputImageHeight wie im Projekt vorhanden
    private final String[] imageNames = {
        "champignonsF.png", "tomatenF.png", "paprikaF.png"   // Beispielnamen
    };

    @FXML
    public void initialize() {
        for (String imageName : imageNames) {
            Image image = new Image(imagePath + imageName);

            Button button = new Button();
            button.setGraphic(createImageView(image));
            button.setStyle("-fx-background-color: transparent;");
            // Klick: ein NEUES ImageView mit demselben Bild rechts anhängen
            button.setOnAction(event ->
                flowPane.getChildren().add(createImageView(image)));

            buttonBox.getChildren().add(button);
        }
    }

    private ImageView createImageView(Image image) {
        ImageView imageView = new ImageView(image);
        imageView.setFitWidth(outputImageWidth);
        imageView.setFitHeight(outputImageHeight);
        imageView.setPreserveRatio(true);
        return imageView;
    }
}
```
