public Polygon createPolygon(int corners, double radius,
                             double x, double y) {
    Polygon polygon = new Polygon();
    for (int i = 0; i < corners; i++) {
        double angle = 2 * Math.PI * i / corners;
        polygon.getPoints().addAll(radius * Math.cos(angle),
                                   radius * Math.sin(angle));
    }
    polygon.setFill(Color.DARKGOLDENROD);
    polygon.setTranslateX(x);   // erst im Ursprung erzeugen, dann verschieben
    polygon.setTranslateY(y);
    polygon.setEffect(new DropShadow());
    return polygon;
}
