public void handleMouseDragged(MouseEvent mouseEvent) {
    Rectangle drag = picture.getDragRectangle();
    drag.setX(Math.min(currPosX, mouseEvent.getX()));
    drag.setY(Math.min(currPosY, mouseEvent.getY()));
    drag.setWidth(Math.abs(mouseEvent.getX() - currPosX));
    drag.setHeight(Math.abs(mouseEvent.getY() - currPosY));
