public void handleMouseReleased(MouseEvent mouseEvent) {
    double x = Math.min(currPosX, mouseEvent.getX());
    double y = Math.min(currPosY, mouseEvent.getY());
    double width = Math.abs(mouseEvent.getX() - currPosX);
    double height = Math.abs(mouseEvent.getY() - currPosY);
    if (width > 0 && height > 0) {
        Rectangle newRectangle = new Rectangle(x, y, width, height);
        newRectangle.setFill(pictureModel.getCurrentFillColor());
        picture.getRectangleList().addNewRectangle(newRectangle);
    }
    picture.getDragRectangle().setWidth(0);
    picture.getDragRectangle().setHeight(0);
    picture.redraw();
