private void drawSceneWithTransformedTrees(GraphicsContext g) {
    g.save();
    g.translate(340, 100);
    drawTree(g);
    g.restore();

    g.save();
    g.translate(200, 80);
    g.scale(1.2, 1.2);
    drawTree(g);
