*(Musterlösung selbst erstellt; die Struktur von DrawOnPane4Rel ist nicht bekannt, der Klassenname ist frei gewählt)*
```java
public class PaneRectangleController {
    private final Pane pane;
    private final Rectangle dragRectangle = new Rectangle();
    private final List<Rectangle> rectangles = new ArrayList<>();
    private double currPosX, currPosY;
    private Color currentFillColor = Color.RED;

    public PaneRectangleController(Pane pane) {
        this.pane = pane;
        dragRectangle.setFill(Color.TRANSPARENT);
        dragRectangle.setStroke(Color.DARKGRAY);
        pane.getChildren().add(dragRectangle);   // Umriss ist ein eigener Knoten
        pane.setOnMousePressed(this::handleMousePressed);
        pane.setOnMouseDragged(this::handleMouseDragged);
        pane.setOnMouseReleased(this::handleMouseReleased);
    }

    private void handleMousePressed(MouseEvent e) {
        currPosX = e.getX();
        currPosY = e.getY();
        dragRectangle.setX(currPosX);
        dragRectangle.setY(currPosY);
        dragRectangle.setWidth(0);
        dragRectangle.setHeight(0);
    }

    private void handleMouseDragged(MouseEvent e) {
        dragRectangle.setWidth(Math.max(0, e.getX() - currPosX));
        dragRectangle.setHeight(Math.max(0, e.getY() - currPosY));
        // kein redraw(): JavaFX zeichnet den Szenengraphen selbst neu
    }

    private void handleMouseReleased(MouseEvent e) {
        double w = e.getX() - currPosX;
        double h = e.getY() - currPosY;
        if (w > 0 && h > 0) {
            Rectangle r = new Rectangle(currPosX, currPosY, w, h);
            r.setFill(currentFillColor);
            rectangles.add(r);
            // unter dem Drag-Rechteck (letzter Knoten) einfügen
            pane.getChildren().add(pane.getChildren().size() - 1, r);
        }
        dragRectangle.setWidth(0);
        dragRectangle.setHeight(0);
    }

    public void removeLastRectangle() {
        if (!rectangles.isEmpty()) {
            pane.getChildren().remove(rectangles.remove(rectangles.size() - 1));
        }
    }

    public void removeAllRectangles() {
        pane.getChildren().removeAll(rectangles);
        rectangles.clear();
    }

    public void setCurrentFillColor(Color color) {
        currentFillColor = color;
    }
}
```
**Es entfallen:** `redraw()`, das Löschen des Canvas und das Durchlaufen der Liste beim Zeichnen. Jedes Rechteck ist ein Knoten im JavaFX-Szenengraphen, und das JavaFX-System übernimmt das Neuzeichnen.

